import { test, expect } from "bun:test";
import { readFileSync } from "fs";
import { join } from "path";
import {
  DEFAULT_WEB_CONCURRENCY,
  OP_HTTP_REQUEST,
  bodyText,
  defWeb,
  encodeBody,
  htmlResponse,
  jsonResponse,
  textResponse,
  type HTTPRequest,
  type HTTPResponse,
} from "./http";
import { concurrencyOf, defThrall, type Ctx } from "./thrall";

// Golden fixtures are generated by the Go source of truth
// (internal/wire: `go test -run TestHTTPGolden -update`) and shared by all three SDKs.
const goldenDir = join(import.meta.dir, "../../../testdata/wire/http");
const golden = (name: string) => JSON.parse(readFileSync(join(goldenDir, `${name}.json`), "utf-8"));

// The same logical cases as httpGoldenCases() in internal/wire/http_test.go, built through the typed
// shapes so a renamed or retyped field fails to line up with the fixture. Bodies are the base64 the
// Go []byte marshalled to.
const cases: Record<string, HTTPRequest | HTTPResponse> = {
  req_get: { method: "GET", path: "/" },
  req_post_binary: {
    method: "POST",
    path: "/upload",
    headers: { "Content-Type": ["application/octet-stream"] },
    body: "AAH/EA==",
  },
  req_query_multi: {
    method: "GET",
    path: "/search",
    query: "q=cats&q=dogs&safe=1",
    headers: { Accept: ["text/html"], "X-Tag": ["a", "b"] },
  },
  req_facts: {
    method: "POST",
    path: "/api/login",
    host: "shop.example",
    scheme: "https",
    client_ip: "203.0.113.7",
    headers: { "X-Forwarded-For": ["203.0.113.7"], "X-Forwarded-Proto": ["https"] },
    body: "eyJ1c2VyIjoiYW5uIn0=",
  },
  resp_html: { status: 200, headers: { "Content-Type": ["text/html; charset=utf-8"] }, body: "PGgxPmhpPC9oMT4=" },
  resp_json: { status: 201, headers: { "Content-Type": ["application/json"] }, body: "eyJvayI6dHJ1ZX0=" },
  resp_cookies: { status: 200, headers: { "Set-Cookie": ["a=1", "b=2"] }, body: "b2s=" },
  resp_minimal: { status: 204 },
};

for (const [name, value] of Object.entries(cases)) {
  test(`${name} matches the Go golden fixture`, () => {
    // Compare parsed values (field order and Go's & query escaping are not significant).
    expect(JSON.parse(JSON.stringify(value))).toEqual(golden(name));
  });
}

test("response constructors set status, content type and a base64 body", () => {
  expect(textResponse(200, "hi")).toEqual({
    status: 200,
    headers: { "Content-Type": ["text/plain; charset=utf-8"] },
    body: encodeBody("hi"),
  });
  expect(htmlResponse(404, "<p>gone</p>").headers?.["Content-Type"]?.[0]).toBe("text/html; charset=utf-8");
  const j = jsonResponse(201, { ok: true });
  expect(j.status).toBe(201);
  expect(bodyText(j)).toBe('{"ok":true}');
});

test("bodyText decodes the Go-produced html fixture", () => {
  expect(bodyText(golden("resp_html") as HTTPResponse)).toBe("<h1>hi</h1>");
});

test("defWeb answers http_request with the handler's response and threads state", async () => {
  const def = defWeb<number>({
    name: "web",
    init: () => 0,
    handle: (req, hits) => [htmlResponse(200, `path=${req.path} hits=${hits + 1}`), hits + 1],
  });
  const handler = def.handleCall?.[OP_HTTP_REQUEST];
  expect(handler).toBeDefined();
  const req: HTTPRequest = { method: "GET", path: "/hello" };
  const [resp, next] = await handler!(req, 4, {} as Ctx);
  expect(next).toBe(5);
  expect(bodyText(resp as HTTPResponse)).toBe("path=/hello hits=5");
});

test("request facts are additive: absent from an old ingress, readable from a new one", async () => {
  const def = defWeb<null>({
    name: "web",
    handle: (req, s) => [textResponse(200, `${req.scheme ?? "?"}://${req.host ?? "?"} from ${req.client_ip ?? "?"}`), s],
  });
  const handler = def.handleCall![OP_HTTP_REQUEST]!;
  // An ingress that predates the facts sends none: the handler sees them as undefined.
  const [fromOld] = await handler({ method: "GET", path: "/" }, null, {} as Ctx);
  expect(bodyText(fromOld as HTTPResponse)).toBe("?://? from ?");
  // A new ingress states them; everything the old contract carried is still where it was.
  const stated = golden("req_facts") as HTTPRequest;
  expect(stated.method).toBe("POST");
  expect(bodyText(stated)).toBe('{"user":"ann"}');
  const [fromNew] = await handler(stated, null, {} as Ctx);
  expect(bodyText(fromNew as HTTPResponse)).toBe("https://shop.example from 203.0.113.7");
});

test("defWeb requires a handler", () => {
  expect(() => defWeb({ name: "x" } as unknown as Parameters<typeof defWeb>[0])).toThrow(/one of handle and serve is required/);
});

const ok = (): HTTPResponse => textResponse(200, "ok");

test("a web definition is one of two shapes, and only serve runs concurrently", () => {
  const handle = (_req: HTTPRequest, s: number): [HTTPResponse, number] => [ok(), s];
  const serve = () => ok();
  expect(concurrencyOf(defWeb<number>({ handle }))).toBe(1);
  expect(concurrencyOf(defWeb<number>({ handle, concurrency: 1 }))).toBe(1);
  expect(concurrencyOf(defWeb<number>({ serve }))).toBe(DEFAULT_WEB_CONCURRENCY);
  expect(concurrencyOf(defWeb<number>({ serve, concurrency: 1 }))).toBe(1);
  expect(concurrencyOf(defWeb<number>({ serve, concurrency: 8 }))).toBe(8);
  // An ordinary thrall is serialized, and has no field through which to say otherwise.
  expect(concurrencyOf(defThrall<number>({ name: "plain", init: () => 0 }))).toBe(1);
  expect(Object.keys(defWeb<number>({ serve, concurrency: 8 }))).not.toContain("concurrency");

  expect(() => defWeb<number>({ handle, serve })).toThrow(/set one/);
  expect(() => defWeb<number>({ handle, concurrency: 4 })).toThrow(/needs serve/);
  expect(() => defWeb<number>({ serve, concurrency: -1 })).toThrow(/non-negative integer/);
  expect(() => defWeb<number>({ serve, concurrency: 1.5 })).toThrow(/non-negative integer/);
});

test("a serve handler has no next state: the shared value comes back as it went in", async () => {
  const shared = { hits: 0 };
  const def = defWeb<{ hits: number }>({
    init: () => shared,
    serve: (req, s) => textResponse(200, `path=${req.path} hits=${++s.hits}`),
  });
  const [resp, next] = await def.handleCall![OP_HTTP_REQUEST]!({ method: "GET", path: "/x" }, shared, {} as Ctx);
  expect(next).toBe(shared);
  expect(bodyText(resp as HTTPResponse)).toBe("path=/x hits=1");
});
